INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('c016fafb-1321-4967-9c69-7fad1fd38a01', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "4de8c240-8cdc-42e9-a5e7-de19ddd15135", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "692466b2-24bc-4546-a848-b40d9dfbd8f5", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "33228604-c596-4537-99b1-56bf7734b7f8", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "01c55682-ac90-436b-a0fa-605206e01f17", "text": "Igaz", "isCorrect": true}, {"id": "8b3b19dd-8a86-4dfb-a038-f238d4441142", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4ff58c67-de6e-48e4-b88b-0666fa6040e5", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "673f4685-6639-48af-a029-476344d66a4c", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "bfb82482-3ae9-4c82-af51-3e380a78631c", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "2c8ec762-4c10-471d-b90b-9602cd7efcd9", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "cc8095a0-4fb5-4060-8ced-60889ff7e055", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "2c1ec2ef-746c-4cf4-b6a9-70fc509b2a30", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "e2290e9b-bd2a-480b-aca4-05f075a30692", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "07b9b89a-6886-4b25-bb29-eb29859f2394", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "3755e7ee-e34f-41b9-b6c9-534152c3fd3b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46f4849b-b805-4220-9299-5973dd31dcf0", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('88e2c066-2dc2-42e2-adad-53aa3a546ab5', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0828c353-1e41-4d86-ae5a-59819d407491", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7c48d1ed-590c-4bfa-b28a-10141ca9b6f4", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "ac3008fc-6f55-4d2a-8d30-b9901397f51a", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "9a39e9ba-aac6-4ed1-b80e-34e0f757dbac", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "4afb93d8-530b-4784-bbb5-ec2dab2fb538", "text": "|-30|", "isCorrect": true}, {"id": "1f0ac9ed-6b93-43e6-b773-b305b8736b56", "text": "|+20|", "isCorrect": false}, {"id": "159e0131-8498-48fb-be2c-8eb10ef6bb44", "text": "Egyenlőek", "isCorrect": false}, {"id": "8c2ca24d-3df0-4986-a396-e384872c0b12", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "6301bac2-ee3e-4b40-b947-4aee9a3a4c14", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "fbbfc15f-43dc-4509-9307-67870721c7c4", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "aa362df3-3be5-4efa-9348-56e5522a8dae", "text": "Igaz", "isCorrect": true}, {"id": "5b98adab-6f30-416a-8158-e7236b50fe55", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "406002bc-e4a4-4ae5-a538-80cc6cb38f51", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4d65fa8b-6089-4d88-8dd3-f4ac05de2f4c", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "f515f6d6-50ad-4cd1-9db8-a90c28723120", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "666fe726-2ce6-4235-9fa8-403770031726", "text": "Igaz", "isCorrect": true}, {"id": "1294c834-b78b-405a-b868-5674c563e368", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6fccaf2d-7dde-4e43-9e35-2e34d5be8bfa", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()),
('4303d578-d5f9-4bbf-a837-2f1029c084fe', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "82e1ddd9-fe3e-409d-a468-576f734a6a91", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "3741f0f5-49e4-4985-b810-501022de4a08", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "fd40ecf4-832f-46b5-a8d1-2e6ba5708db3", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "6e0a4425-88d2-49d3-8361-bc6fd01dfc1f", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "fb9cfb00-c8df-40fd-9fe9-6f3db3ddf530", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "5b91203b-2ae4-46de-813a-0ab1d1da0887", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "fb5db186-bab9-43de-ba5c-ebba141186a7", "text": "Igaz", "isCorrect": true}, {"id": "ffe6fc1b-a126-4359-a937-5e92547a058c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "662b1bce-8065-455f-aa9f-c62c103fcc28", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "76a99289-7c44-47d3-a256-d472b305e010", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "f8a53f40-5234-4088-a459-72688a196979", "text": "45", "isCorrect": true}, {"id": "9c3c154e-a9c4-4521-980c-6f0a2bf2312e", "text": "5", "isCorrect": false}, {"id": "83b32335-dcc4-4110-92f2-f8a58655b043", "text": "3", "isCorrect": false}, {"id": "1028fd3f-fae0-4d3a-843d-67cdf358b6b7", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "7fd24697-a5d5-4c82-bd4d-d2dd298ece1e", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "fd1ae599-627c-4441-891f-1bdceba96c9e", "text": "Igaz", "isCorrect": true}, {"id": "922c46aa-3745-4dc8-8a9e-c0c98a4c97d6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "90e21a6e-c515-483a-b2dd-f707871d3ab2", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "8d5fd933-25c8-4896-8297-f5d4df26e191", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('6e5fbaf4-361d-40b4-99a2-84c40026bb0d', '21feff02-016d-46e2-bb9d-c27495133b1b', '14. óra: Számolás maradékokkal', 'Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "35126470-b307-4f08-ad14-06910dfe1f9c", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "6e231ef8-9ea3-4e7b-855b-24874ac94653", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "505ddabe-ef80-44d3-8217-cf0211dc5636", "text": "Igaz", "isCorrect": true}, {"id": "0ab416e5-3563-4e5d-b5ca-1222f9390cce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1f3d86d-89be-46b8-ab8f-b6a9ca135970", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "4de65a00-3375-4dcd-a867-9443fdcda1fb", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "d11c78d7-df6b-41c9-95a4-41728d03d55f", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "2c157530-245c-40a3-8399-a690b7a9c03e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b93f273f-f405-4c2b-b6ce-d580d6e69322", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "f543df56-b11f-4f32-9a49-11b893a5ff75", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "adf73029-8c97-44e6-8314-67d77ffd1b3f", "text": "Igaz", "isCorrect": true}, {"id": "71661746-94fd-4c47-99c6-3c99f9118179", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "96ae8af1-365e-4063-abde-ab8a69c901d4", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "f103feb6-899c-4387-a92a-9120e69408a8", "text": "15", "isCorrect": true}, {"id": "9e67157e-f15d-48b6-a844-c227ce0deb2a", "text": "16", "isCorrect": false}, {"id": "5a4e8396-487a-4660-9240-50032c2f1fea", "text": "17", "isCorrect": false}, {"id": "06f4133d-5a55-4cd9-8e27-90e579d5217a", "text": "19", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('56103a09-0190-4388-a92a-edc5fe49e8f1', '21feff02-016d-46e2-bb9d-c27495133b1b', '15. óra: Hány osztója van?', 'Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "184330fb-0cc2-4408-adbc-47fa736e2987", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "b58d7e1a-2c8b-4864-b33c-3c6d5bdfebda", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "1b86de25-b6e8-45ef-9e50-0c8cb133442c", "text": "Összetett számok", "isCorrect": false}, {"id": "b26c6ce5-9f0f-4c1a-b07c-547f562b0b4c", "text": "Páros számok", "isCorrect": false}, {"id": "c291cefc-267e-443b-9816-90998bc8c279", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "17c8a520-6c59-4f88-935e-3585c86744b1", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "77f21674-fef8-45dc-9b95-6e58fa5cf041", "text": "Igaz", "isCorrect": false}, {"id": "e82c4223-2fcf-4302-a37c-4099f3e64338", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "6dc0312e-8eed-4190-9f57-996c6e4c018b", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "3716ede1-8a51-4e4d-8c47-ed165717fa39", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e9c47e92-5c6f-41cc-89ad-595ffcdcbd5a", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "dc9247a8-23ed-4edd-80b8-3cce3c2f0b5a", "text": "Igaz", "isCorrect": true}, {"id": "82575e64-3a11-4d52-9028-cedbca62c3fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6712d466-1275-4711-9e8c-ca03c3585720", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "495ad178-33db-422a-9d87-44b51d61d228", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "9867b6e0-32c2-45c2-90f8-037340694593", "text": "13", "isCorrect": true}, {"id": "b98427d7-ea44-4b02-97dc-578abe7f7ef1", "text": "9", "isCorrect": false}, {"id": "9d656aab-f09a-42ba-8d8a-6a7354644087", "text": "15", "isCorrect": false}, {"id": "ccd2943f-9aa8-4088-9bca-c23b7df3f115", "text": "21", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());